package ticket

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/spf13/cobra"
)

// defaultStartAgent is the agent launched when --agent is not supplied.
const defaultStartAgent = "claude-code"

// newStartCmd builds `entire ticket start`.
func newStartCmd(deps Deps) *cobra.Command {
	var agentName string
	var force bool
	cmd := &cobra.Command{
		Use:   "start <ticket-id>",
		Short: "Link a ticket and launch an agent to work it",
		Long: `Link a ticket to the current branch and launch a coding agent to work on it.
Equivalent to ` + "`entire ticket link`" + ` followed by starting an agent with the
ticket as context.

Examples:
  entire ticket start ENG-142
  entire ticket start ENG-142 --agent claude-code`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			id := ""
			if len(args) == 1 {
				id = args[0]
			}
			return runStart(cmd.Context(), cmd.OutOrStdout(), deps, id, agentName, force)
		},
	}
	cmd.Flags().StringVar(&agentName, "agent", "", "agent to launch (default claude-code)")
	cmd.Flags().BoolVar(&force, "force", false, "overwrite an existing link on this branch")
	return cmd
}

func runStart(ctx context.Context, out io.Writer, deps Deps, id, agentName string, force bool) error {
	if deps.LaunchFix == nil {
		return errors.New("ticket start is unavailable: no agent launcher configured")
	}

	link, branch, err := linkCurrentBranch(ctx, id, force)
	if err != nil {
		return err
	}

	if agentName == "" {
		agentName = defaultStartAgent
	}

	fmt.Fprintf(out, "✓ Linked %s to branch %q. Launching %s …\n", link.ID, branch, agentName)
	return deps.LaunchFix(ctx, agentName, composeStartPrompt(link))
}

// composeStartPrompt builds the agent prompt for a start run. Once platform
// providers land, this embeds the fetched ticket title/body/acceptance; today
// it references the ticket by ID so the agent can look it up.
func composeStartPrompt(link Link) string {
	var b strings.Builder
	fmt.Fprintf(&b, "Work on ticket %s (%s).\n\n", link.ID, link.Platform)
	b.WriteString("Implement the change the ticket describes on the current branch, ")
	b.WriteString("following the conventions already present in this codebase. ")
	b.WriteString("When you are done, make sure the work matches what the ticket asked for.\n")
	return b.String()
}

package cli

// ticket_bridge.go wires cli-package implementations into the ticket
// subpackage's NewCommand Deps struct. The bridge lives in the cli package so
// the ticket subpackage does not import the per-agent packages (import cycle).

import (
	"github.com/entireio/cli/cmd/entire/cli/agentlaunch"
	"github.com/entireio/cli/cmd/entire/cli/ticket"
)

// buildTicketDeps builds the ticket.Deps used by ticket.NewCommand.
func buildTicketDeps() ticket.Deps {
	return ticket.Deps{
		LaunchFix: agentlaunch.LaunchFixAgent,
	}
}

