func TestComposeStartPrompt(t *testing.T) {
	t.Parallel()

	prompt := composeStartPrompt(Link{Platform: "linear", ID: "ENG-142"})
	assert.Contains(t, prompt, "ENG-142")
	assert.Contains(t, prompt, "linear")
	assert.True(t, strings.HasPrefix(prompt, "Work on ticket ENG-142"))
