	return cmd
}

func runStart(ctx context.Context, out io.Writer, deps Deps, id, agentName string, force, dryRun bool) error {
	if !dryRun && deps.LaunchFix == nil {
		return errors.New("ticket start is unavailable: no agent launcher configured")
	}

	link, branch, err := linkCurrentBranch(ctx, id, force)
	if err != nil {
		return err
	}

	if agentName == "" {
		agentName = defaultStartAgent
	}

	// Fetch the ticket so the prompt carries its title/body. In a normal run a
	// fetch failure must not block launching the agent; --dry-run surfaces it.
	task, fetchErr := fetchTaskForStart(ctx, link)
	prompt := composeStartPrompt(link, task)

	if dryRun {
		fmt.Fprintf(out, "Linked %s to branch %q (dry run — no agent launched).\n\n", link.ID, branch)
		switch {
		case fetchErr != nil:
			fmt.Fprintf(out, "Ticket fetch failed: %v\n\n", fetchErr)
		case task != nil:
			fmt.Fprintf(out, "Fetched %s: %s [%s]\n%s\n\n", task.ID, task.Title, task.State, task.URL)
		}
		fmt.Fprintln(out, "--- prompt the agent would receive ---")
		fmt.Fprint(out, prompt)
		return nil
	}

	fmt.Fprintf(out, "✓ Linked %s to branch %q. Launching %s …\n", link.ID, branch, agentName)
	return deps.LaunchFix(ctx, agentName, prompt)
}

// fetchTaskForStart resolves the linked ticket via the active provider,
// returning a nil task (and the error) when it cannot be fetched.
func fetchTaskForStart(ctx context.Context, link Link) (*Task, error) {
	prov, err := activeProvider(ctx)
	if err != nil {
		return nil, err
	}
	task, err := prov.Fetch(ctx, link.ID)
	if err != nil {
		return nil, err
	}
	return &task, nil
}

